                TRANS_TYPE.TOPUP,
                TRANS_TYPE.SOFTPIN,
                TRANS_TYPE.DISBURSEMENT,
                TRANS_TYPE.BANK_TRANSFER
            ]
        }
    };

    if (params.transId) {
